{
  "openapi": "3.1.0",
  "info": {
    "title": "Eigenpal API",
    "version": "1.0.0",
    "description": "Public REST API for inspecting automations, starting and monitoring runs, managing files, collecting human reviews, and running evaluations.",
    "contact": {
      "name": "Eigenpal",
      "url": "https://eigenpal.com"
    },
    "license": {
      "name": "Apache-2.0",
      "url": "https://www.apache.org/licenses/LICENSE-2.0"
    }
  },
  "servers": [
    {
      "url": "https://api.eigenpal.com",
      "description": "Production (canonical API hostname)"
    }
  ],
  "security": [
    {
      "bearerAuth": []
    }
  ],
  "tags": [
    {
      "name": "Metadata",
      "description": "Authenticate and inspect the current API context."
    },
    {
      "name": "Models",
      "description": "List text, vision, and OCR models configured for the current tenant environment. This is a catalog inventory, not a live provider health probe."
    },
    {
      "name": "Automations",
      "description": "Inspect runnable workflow and agent automations, their versions, triggers, and source sync state."
    },
    {
      "name": "Runs",
      "description": "Start, monitor, retry, review, and debug automation runs, including artifacts."
    },
    {
      "name": "Reviews",
      "description": "Record human review verdicts, manage corrected outputs, and monitor review health."
    },
    {
      "name": "Files",
      "description": "Upload reusable files for later run or dataset use."
    },
    {
      "name": "Templates",
      "description": "Upload, inspect, version, download, and delete tenant-scoped DOCX and XLSX templates."
    },
    {
      "name": "Evaluation",
      "description": "Manage datasets, examples, evaluators, experiment batches, evaluator scores, and run promotion workflows."
    }
  ],
  "paths": {
