          {
            "in": "path",
            "name": "id",
            "schema": {
              "type": "string",
              "description": "Automation id or typed alias."
            },
            "required": true,
            "description": "Automation id or typed alias."
          },
          {
            "in": "query",
            "name": "exampleIds",
            "schema": {
              "description": "Optional comma-separated dataset example ids to export. Omit to export the full dataset.",
