    "/v1/automations/{id}/examples": {
      "get": {
        "operationId": "automations.examples.list",
        "summary": "List dataset examples",
        "description": "List dataset examples for one automation. Examples contain input, expected output, expected files, metadata, and optional overrides used by evaluation runs. Pass `include=metadata` to return ids, names, metadata, and expected file refs without loading input or expected JSON.",
        "tags": [
          "Evaluation"
        ],
        "parameters": [
          {
            "in": "path",
            "name": "id",
            "schema": {
              "type": "string",
              "description": "Automation id or typed alias, such as `workflows.slug` or `agents.slug`."
            },
            "required": true,
            "description": "Automation id or typed alias, such as `workflows.slug` or `agents.slug`."
          },
          {
            "in": "query",
            "name": "limit",
            "schema": {
              "description": "Maximum number of examples to return.",
              "type": "integer",
              "minimum": 1,
              "maximum": 100
            },
            "description": "Maximum number of examples to return."
          },
          {
            "in": "query",
            "name": "offset",
            "schema": {
              "description": "Zero-based offset for paging through examples.",
              "type": "integer",
              "minimum": 0,
              "maximum": 9007199254740991
            },
            "description": "Zero-based offset for paging through examples."
          },
          {
            "in": "query",
            "name": "include",
            "schema": {
              "description": "Response payload scope. `metadata` returns ids, names, metadata, and expected file refs without loading input or expected JSON.",
              "type": "string",
              "enum": [
                "full",
                "metadata"
              ]
            },
            "description": "Response payload scope. `metadata` returns ids, names, metadata, and expected file refs without loading input or expected JSON."
          }
        ],
        "responses": {
          "200": {
            "description": "Page of dataset examples.",
